package com.example.ai

import android.content.Context
import android.util.Log

/**
 * Provides the API key for MailCraft AI assistant features.
 * Safely resolves from:
 * 1. User runtime key (saved in SharedPreferences)
 * 2. BuildConfig.OPENROUTER_API_KEY generated by build.gradle.kts / GitHub Actions secrets
 * 3. Secrets Gradle Plugin field
 * 4. System environment variables
 */
object AiKeyProvider {
  private const val TAG = "AiKeyProvider"
  private const val PREFS_NAME = "mailcraft_ai_prefs"
  private const val KEY_API_SECRET = "custom_openrouter_api_key"

  @Volatile
  private var inMemoryKey: String = ""

  fun saveCustomKey(context: Context, key: String) {
    inMemoryKey = key.trim()
    try {
      context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        .edit()
        .putString(KEY_API_SECRET, inMemoryKey)
        .apply()
    } catch (e: Exception) {
      Log.w(TAG, "Failed to persist custom key to SharedPreferences: ${e.message}")
    }
  }

  fun getApiKey(context: Context? = null): String {
    // 1. Check in-memory key
    if (inMemoryKey.isNotBlank()) return inMemoryKey

    // 2. Check SharedPreferences if context is available
    if (context != null) {
      try {
        val saved = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
          .getString(KEY_API_SECRET, "")
          .orEmpty()
          .trim()
        if (saved.isNotBlank()) {
          inMemoryKey = saved
          return saved
        }
      } catch (_: Exception) {}
    }

    // 3. Check direct BuildConfig.OPENROUTER_API_KEY
    val directKey = try {
      val key = com.example.BuildConfig.OPENROUTER_API_KEY
      if (key.isNotBlank() && key != "YOUR_API_KEY") key.trim() else ""
    } catch (_: Throwable) {
      ""
    }
    if (directKey.isNotBlank()) {
      inMemoryKey = directKey
      return directKey
    }

    // 4. Check Secrets Gradle Plugin reflection field (openrouter_api)
    val secretsKey = try {
      val field = com.example.BuildConfig::class.java.getField("openrouter_api")
      val v = field.get(null) as? String ?: ""
      if (v.isNotBlank() && v != "YOUR_API_KEY") v.trim() else ""
    } catch (_: Throwable) {
      ""
    }
    if (secretsKey.isNotBlank()) {
      inMemoryKey = secretsKey
      return secretsKey
    }

    // 5. Check environment variables
    val envKey = (System.getenv("openrouter_api") ?: System.getenv("OPENROUTER_API") ?: "").trim()
    if (envKey.isNotBlank() && envKey != "YOUR_API_KEY") {
      inMemoryKey = envKey
      return envKey
    }

    return ""
  }

  fun hasValidKey(context: Context? = null): Boolean = getApiKey(context).isNotBlank()
}
